print("== FILE PRESENCE ==")
for f in files:
    print(("OK      " if (D/f).exists() else "MISSING ") + f)

print("\n== achados.json ==")
data = json.loads((D/'achados.json').read_text(encoding='utf-8'))
print("count =", len(data), "| is list:", isinstance(data, list))
ENUM = {"anuencia","preco","indenizacao","prazo","nenhum"}
PREF = ("data room §","minuta cl. ","cliente — ")
errs = []
for i, e in enumerate(data, 1):
    missing = [k for k in ("achado","onde","por_que_importa","efeito","solucao") if k not in e]
    if missing: errs.append(f"#{i} missing keys: {missing}")
    ef = e.get("efeito")
    if ef not in ENUM: errs.append(f"#{i} efeito INVALID: {ef!r}")
    for seg in [s.strip() for s in e.get("onde","").split(";") if s.strip()]:
        if not any(seg.startswith(p) for p in PREF):
            errs.append(f"#{i} onde seg BAD: {seg!r}")
print("efeito list:", [e.get("efeito") for e in data])
print("last achado onde:", data[-1].get("onde"))
if errs:
    print("ERRORS:")
    for x in errs: print(" -", x)
else:
    print("schema keys / efeito enum / onde prefixes: ALL OK")

print("\n== TWINS ==")
same = (D/'PERGUNTAS.md').read_bytes() == (D/'QUESTIONS.md').read_bytes()
print("PERGUNTAS.md vs QUESTIONS.md:", "IDENTICAL" if same else "DIFFER!!")

white = {'ctn_133_sucessao','clt_10_448_sucessao_trabalhista','cade_limiares',
         'lei14133_alteracao_societaria','cc_1147_nao_concorrencia',
         'sandbagging_franquia_mercado','earnout_pratica'}
def norm(tok):
    t = tok.strip()
    for pre in ("workspace/library/","library/","workspace/"):
        if t.startswith(pre): t = t[len(pre):]
    if t.endswith('.md'): t = t[:-3]
    return t
internal = {
    "achados.json","redline.md","STATUS.md","PERGUNTAS.md","QUESTIONS.md",
    "resposta_advogado_comprador.md","nota_socios.md","working/calc.py","calc.py",
    "INDEX.md","library/INDEX.md","workspace/library/INDEX.md","CONTRACT.md",
    "library/","workspace/library/","data room §1.1",
}
scan = ["redline.md","resposta_advogado_comprador.md","nota_socios.md",
        "PERGUNTAS.md","STATUS.md","achados.json"]
print("\n== CITATION SWEEP (backticked) ==")
unknown = {}
ismap = {}
for f in scan:
    text = (D/f).read_text(encoding='utf-8')
    for tok in re.findall(r'`([^`\n]+)`', text):
        t0 = tok.strip()
        if not t0 or t0 in internal or t0.endswith('/'):
            continue
        n = norm(t0)
        if n in white or n == "INDEX":
            ismap.setdefault(t0, f).append(f)
            continue
        unknown.setdefault(t0, {}).setdefault(f, 0)
        unknown[t0][f] += 1
if unknown:
    for t0, per in unknown.items():
        print(f"UNKNOWN `{t0}` -> {per}")
else:
    print("all backticked citations resolve to library whitelist or internal cross-refs")
print("library-cited tokens (whitelist hits):", sorted(ismap))
print("\n== RAW library/ mentions outside whitelist ==")
raw_bad = False
for f in scan:
    text = (D/f).read_text(encoding='utf-8')
    for m in re.finditer(r'(?:workspace/)?library/[A-Za-z0-9_.\-]+', text):
        base = m.group(0).split('/')[-1]
        if base not in {w + '.md' for w in white} | {"INDEX.md"}:
            print(f"  {f}: {m.group(0)}")
            raw_bad = True
if not raw_bad: print("none")

print("\n== calc.py ==")
r = subprocess.run(['python3','/work/workspace/working/calc.py'], capture_output=True, text=True)
print("returncode:", r.returncode)
for s in ("1,302,000.00","504,000.00","1,020,000","466,666.67","5,133,333.33","122.2222%"):
    print(("OK  " if s in r.stdout else "MISS ") + s)

